  constructor() {
    this.seconds = 0;
  }
  start() {
    setInterval(() => {
      this.seconds += 1;
      console.log(this.seconds);
    }, 1000);
  }
}
new Timer().start();
```

Now `this` refers to the `Timer` instance, and `this.seconds` increments correctly on each cycle.

